import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int u, v;
        long capacity, flow;
        long cost;
        Edge(int u, int v, long capacity, long flow, long cost) {
            this.u = u;
            this.v = v;
            this.capacity = capacity;
            this.flow = flow;
            this.cost = cost;
        }
        long remaining() {
            return capacity - flow;
        }
    }

    static ArrayList<Integer>[] g;
    static ArrayList<Edge> e;
    static long[] dist;
    static long[] bottleneck;
    static int[] parent;
    static boolean[] inQueue;
    static final long INF = Long.MAX_VALUE;

    static void addEdge(int u, int v, long cap, long cst) {
        g[u].add(e.size());
        e.add(new Edge(u, v, cap, 0, cst));
        g[v].add(e.size());
        e.add(new Edge(v, u, 0, 0, -cst));
    }

    static long totalCost;
    static long totalFlow;

    static void minCostMaxFlow(int s, int t) {
        Arrays.fill(inQueue, false);
        totalFlow = 0;
        totalCost = 0;
        while (true) {
            Arrays.fill(dist, INF);
            dist[s] = 0;
            Arrays.fill(parent, -1);
            parent[s] = 0;
            Arrays.fill(bottleneck, 0);
            bottleneck[s] = Long.MAX_VALUE;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            inQueue[s] = true;
            while (!q.isEmpty()) {
                int u = q.poll();
                inQueue[u] = false;
                for (int idx : g[u]) {
                    Edge edge = e.get(idx);
                    if (edge.remaining() > 0 && dist[edge.v] > dist[u] + edge.cost + 1e-9) {
                        dist[edge.v] = dist[u] + edge.cost;
                        parent[edge.v] = idx;
                        bottleneck[edge.v] = Math.min(bottleneck[u], edge.remaining());
                        if (!inQueue[edge.v]) {
                            q.offer(edge.v);
                            inQueue[edge.v] = true;
                        }
                    }
                }
            }
            if (parent[t] < 0) break;
            long flowAdd = bottleneck[t];
            totalFlow += flowAdd;
            totalCost += flowAdd * dist[t];
            for (int v = t; v != s; v = e.get(parent[v]).u) {
                e.get(parent[v]).flow += flowAdd;
                e.get(parent[v] ^ 1).flow -= flowAdd;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int totalNodes = 6 + 107 * n;
        g = new ArrayList[totalNodes];
        for (int i = 0; i < totalNodes; i++) {
            g[i] = new ArrayList<>();
        }
        e = new ArrayList<>();
        dist = new long[totalNodes];
        parent = new int[totalNodes];
        bottleneck = new long[totalNodes];
        inQueue = new boolean[totalNodes];

        for (int i = 0; i < k; i++) {
            int x = Integer.parseInt(br.readLine()) - 1;
            addEdge(0, x + 1, 1, 0);
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken()) - 1;
            int y = Integer.parseInt(st.nextToken()) - 1;
            for (int i2 = 0; i2 < 105; i2++) {
                for (int j = 0; j < 51; j++) {
                    addEdge(i2 * n + x + 1, (i2 + 1) * n + y + 1, 1, c + d * (2 * j + 1));
                    addEdge(i2 * n + y + 1, (i2 + 1) * n + x + 1, 1, c + d * (2 * j + 1));
                }
            }
        }

        for (int i2 = 0; i2 < 105; i2++) {
            for (int j = 0; j < n; j++) {
                addEdge(i2 * n + j + 1, (i2 + 1) * n + j + 1, 51, c);
            }
        }

        for (int i2 = 0; i2 < 105; i2++) {
            addEdge(i2 * n + 1, 105 * n + 1, 51, 0);
        }

        minCostMaxFlow(0, 105 * n + 1);
        System.out.println(totalCost);
    }
}
